script:
frappe.ui.form.on("Student", {
    validate: function (frm) {
        const phone = (frm.doc.phone || "").trim();
        if (/^\d{10}$/.test(phone)) {
            frm.set_value("phone", `91${phone}`);
            return;
        }
        if (/^91\d{10}$/.test(phone)) {
            frm.set_value("phone", phone);
            return;
        }
        frappe.throw(__("Phone must be exactly 10 digits or 12 digits starting with 91."));
    },
});
